<?php
declare(strict_types=1);
$teamPending = array_sum(array_map(static fn (array $member): int => (int) $member['pending_count'], $managerWorkload));
$teamActive = array_sum(array_map(static fn (array $member): int => (int) $member['open_count'], $managerWorkload));
$teamAssignedTasks = count(array_filter($teamTasks, static fn (array $task): bool => $task['state'] === 'assigned'));
$teamValidatingTasks = count(array_filter($teamTasks, static fn (array $task): bool => $task['state'] === 'submitted'));
$teamMax = max(1, ...array_map(static fn (array $member): int => (int) $member['open_count'], $managerWorkload));
$teamScope = ($_GET['team_scope'] ?? '') === 'loaded' ? 'loaded' : 'all';
$teamSelection = ($_GET['team_selection'] ?? '') === 'all' ? 'all' : '3';
$teamVisibleWorkload = $teamScope === 'loaded' ? array_values(array_filter($managerWorkload, static fn (array $member): bool => (int) $member['open_count'] > 0)) : $managerWorkload;
if ($teamSelection === '3') { $teamVisibleWorkload = array_slice($teamVisibleWorkload, 0, 3); }
$teamVisibleTotal = array_sum(array_map(static fn (array $member): int => (int) $member['open_count'], $teamVisibleWorkload));
$teamVisiblePending = array_sum(array_map(static fn (array $member): int => (int) $member['pending_count'], $teamVisibleWorkload));
$teamVisibleWaiting = array_sum(array_map(static fn (array $member): int => (int) $member['waiting_count'], $teamVisibleWorkload));
$teamVisibleProgress = array_sum(array_map(static fn (array $member): int => (int) $member['in_progress_count'] - (int) $member['waiting_count'], $teamVisibleWorkload));
$teamVisibleStale = array_sum(array_map(static fn (array $member): int => (int) $member['stale_count'], $teamVisibleWorkload));
?>
<div class="team-page">
  <header class="team-page__header"><span class="team-page__symbol" aria-hidden="true">♙</span><div><h1>Equipo y tareas</h1><p>Supervisa la distribución del trabajo, las actividades delegadas y las validaciones del equipo.</p></div></header>
  <nav class="team-tabs" aria-label="Secciones de equipo y tareas"><a href="/dashboard?section=team&amp;tab=workload" <?= $teamTab === 'workload' ? 'aria-current="page"' : '' ?>>Carga del equipo</a><a href="/dashboard?section=team&amp;tab=tasks" <?= $teamTab === 'tasks' ? 'aria-current="page"' : '' ?>>Tareas asignadas</a><a href="/dashboard?section=team&amp;tab=validation" <?= $teamTab === 'validation' ? 'aria-current="page"' : '' ?>>Validaciones pendientes</a></nav>
  <div class="team-kpis"><a href="/csi/requests?status=<?= (int) $pendingStatusId ?>&amp;assignment=assigned" class="team-kpi"><span class="team-kpi__icon">▤</span><span><strong>Trabajos sin iniciar</strong><b><?= $teamPending + $teamAssignedTasks ?></b><small><?= $teamPending ?> solicitudes · <?= $teamAssignedTasks ?> tareas delegadas</small></span></a><a href="/csi/requests?alert=stale" class="team-kpi"><span class="team-kpi__icon team-kpi__icon--amber">◷</span><span><strong>Solicitudes con demora</strong><b><?= (int) $teamStaleCount ?></b><small>Sin movimientos durante 48 horas</small></span></a><a href="/dashboard?section=team&amp;tab=validation" class="team-kpi"><span class="team-kpi__icon team-kpi__icon--violet">♢</span><span><strong>Validaciones pendientes</strong><b><?= (int) $managerPendingValidation ?></b><small><?= $teamValidatingTasks ?> tareas recientes enviadas a revisión</small></span></a></div>
  <?php if ($teamStaleCount > 0): ?><div class="team-alert" role="status"><span class="team-alert__icon" aria-hidden="true">⚠</span><div class="team-alert__message"><strong>Situaciones que requieren supervisión</strong><span><?php if ($teamStaleExample !== null && is_string($teamStaleExample['technician_name'] ?? null)): ?><b><?= $e(\App\Presentation\DisplayName::withoutDemoMarker($teamStaleExample['technician_name'])) ?></b> tiene una solicitud con demora que requiere revisar su avance.<?php else: ?>Hay <?= (int) $teamStaleCount ?> solicitudes con demora que requieren revisar su avance.<?php endif; ?></span></div><div class="team-alert__actions"><a class="team-alert__primary" href="<?= $teamStaleExample !== null ? '/csi/requests/' . rawurlencode($teamStaleExample['public_code']) : '/csi/requests?alert=stale' ?>">Consultar trabajo <span aria-hidden="true">→</span></a><a class="team-alert__secondary" href="/csi/requests?alert=stale">Ver todos los trabajos<br>con demora</a></div></div><?php endif; ?>
  <?php if ($teamTab === 'workload'): ?>
  <section class="team-panel team-panel--distribution"><header><div><h2>Distribución del trabajo por integrante</h2><p><?= count($teamVisibleWorkload) ?> responsables mostrados · <?= $teamVisibleTotal ?> solicitudes activas en esta selección</p></div><div class="team-panel__controls"><form method="get" action="/dashboard"><input type="hidden" name="section" value="team"><select name="team_scope" aria-label="Filtrar integrantes" onchange="this.form.requestSubmit()"><option value="all" <?= $teamScope === 'all' ? 'selected' : '' ?>>Asignaciones activas</option><option value="loaded" <?= $teamScope === 'loaded' ? 'selected' : '' ?>>Solo personal con carga</option></select><input type="hidden" name="team_selection" value="<?= $e($teamSelection) ?>"></form><form method="get" action="/dashboard"><input type="hidden" name="section" value="team"><input type="hidden" name="team_scope" value="<?= $e($teamScope) ?>"><select name="team_selection" aria-label="Cantidad de integrantes" onchange="this.form.requestSubmit()"><option value="3" <?= $teamSelection === '3' ? 'selected' : '' ?>>Selección parcial (<?= count($teamVisibleWorkload) ?>)</option><option value="all" <?= $teamSelection === 'all' ? 'selected' : '' ?>>Todo el equipo</option></select></form><a href="/dashboard?section=team&amp;team_selection=all">Ver todo el equipo →</a></div></header>
    <div class="team-table-wrap"><table class="team-table"><thead><tr><th>Integrante</th><th>Sin iniciar</th><th>En atención</th><th>En espera</th><th>Total activo</th><th>Distribución de atenciones</th><th>Con demora</th><th>Acciones</th></tr></thead><tbody><?php foreach ($teamVisibleWorkload as $member): ?><?php $pending = (int) $member['pending_count']; $waiting = (int) $member['waiting_count']; $progress = (int) $member['in_progress_count'] - $waiting; $total = (int) $member['open_count']; $stale = (int) $member['stale_count']; $name = \App\Presentation\DisplayName::withoutDemoMarker($member['name']); $parts = preg_split('/\s+/u', trim($name)) ?: []; $initials = mb_strtoupper(mb_substr($parts[0] ?? '', 0, 1) . mb_substr($parts[1] ?? '', 0, 1)); ?><tr><th scope="row"><span class="team-avatar"><?= $e($initials) ?></span><span><?= $e($name) ?><small><?= $member['role_code'] === 'csi_manager' ? 'Responsable del CSI' : 'Técnico CSI' ?></small></span></th><td><?= $pending ?></td><td class="team-table__progress"><?= $progress ?></td><td class="team-table__waiting"><a href="/csi/requests?technician=<?= (int) $member['id'] ?>&amp;validation=pending" aria-label="Ver solicitudes en espera de validación de <?= $e($name) ?>"><?= $waiting ?></a></td><td><strong><?= $total ?></strong></td><td><div class="team-bar" role="img" aria-label="<?= $pending ?> sin iniciar, <?= $progress ?> en atención y <?= $waiting ?> en espera de validación; escala máxima <?= $teamMax ?> solicitudes"><span style="width:<?= 100 * $pending / $teamMax ?>%"></span><span style="width:<?= 100 * $progress / $teamMax ?>%"></span><span style="width:<?= 100 * $waiting / $teamMax ?>%"></span></div><small><?= $total ?> solicitudes activas</small></td><td><span class="team-delay <?= $stale > 0 ? 'team-delay--active' : '' ?>"><?= $stale ?></span></td><td><a class="team-action" href="/csi/requests?technician=<?= (int) $member['id'] ?>&amp;open=1">Ver trabajos</a></td></tr><?php endforeach; ?></tbody><tfoot><tr><th scope="row">TOTAL · Selección actual</th><td><?= $teamVisiblePending ?></td><td class="team-table__progress"><?= $teamVisibleProgress ?></td><td class="team-table__waiting"><?= $teamVisibleWaiting ?></td><td><?= $teamVisibleTotal ?></td><td><small><?= $teamVisibleTotal ?> solicitudes únicas</small></td><td><?= $teamVisibleStale ?></td><td><?= count($teamVisibleWorkload) ?> responsables</td></tr></tfoot></table></div><footer><div class="team-legend"><span><i></i>Sin iniciar</span><span><i></i>En atención</span><span><i></i>En espera de validación</span><span><i></i>Demora: indicador adicional</span></div><span>Escala común de barras: máximo <?= $teamMax ?> solicitudes</span></footer>
  </section>
  <?php elseif ($teamTab === 'tasks'): ?>
  <section class="team-panel"><header><div><h2>Tareas delegadas activas</h2><p>Trabajos asignados a practicantes y enviados a validación.</p></div></header><?php if ($teamTasks === []): ?><p class="team-empty">No hay tareas delegadas activas.</p><?php else: ?><div class="team-table-wrap"><table class="team-table"><thead><tr><th>Solicitud</th><th>Practicante</th><th>Responsable</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach ($teamTasks as $task): ?><tr><td><a href="/csi/requests/<?= rawurlencode($task['public_code']) ?>"><?= $e($task['public_code']) ?></a><small><?= $e($task['title']) ?></small></td><td><?= $e(\App\Presentation\DisplayName::withoutDemoMarker($task['intern_name'])) ?></td><td><?= $e(\App\Presentation\DisplayName::withoutDemoMarker($task['responsible_name'])) ?></td><td><?= $task['state'] === 'submitted' ? 'Por validar' : 'Asignada' ?></td><td><a class="team-action" href="/csi/requests/<?= rawurlencode($task['public_code']) ?>">Ver tarea</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
  <?php else: ?>
  <section class="team-panel"><header><div><h2>Validaciones pendientes</h2><p>Tareas que requieren revisión o confirmación del responsable.</p></div><a href="/csi/requests?validation=pending">Ver todas →</a></header><?php if ($teamFollowUp['pending_validation'] === []): ?><p class="team-empty">No hay tareas pendientes de validación.</p><?php else: ?><div class="team-table-wrap"><table class="team-table"><thead><tr><th>Solicitud</th><th>Practicante</th><th>Responsable</th><th>Acción</th></tr></thead><tbody><?php foreach ($teamFollowUp['pending_validation'] as $task): ?><tr><td><a href="/csi/requests/<?= rawurlencode($task['public_code']) ?>"><?= $e($task['public_code']) ?></a><small><?= $e($task['title']) ?></small></td><td><?= $e(\App\Presentation\DisplayName::withoutDemoMarker($task['intern_name'])) ?></td><td><?= $e(\App\Presentation\DisplayName::withoutDemoMarker($task['responsible_name'])) ?></td><td><a class="team-action" href="/csi/requests/<?= rawurlencode($task['public_code']) ?>">Revisar tarea</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
  <?php endif; ?>
</div>
